export default function ({ result, send, source, data }) {
  return {
    body: JSON.stringify({
      ...result,
      has_urgent_items: send,
      summary_source: source,
      blocked_thread_count: data.blocked_thread_count,
      blocked_examples_text: data.blocked_examples_text,
      email_count_24h: data.email_count_24h,
      ntfy_title:
        "Daily Email Summary | " +
        data.email_count_24h +
        " mails | " +
        new Date().toISOString().slice(0, 10),
    }),
  };
}
